          "title": "Un Banquete Demasiado Rápido",
          "text": "¡Iniciando escáneres! Vamos a viajar a la velocidad de la luz para analizar muy de cerca qué ocurre en este rincón de la galaxia.\n\nEl reporte oficial de la NASA nos explica lo siguiente sobre esta imagen de nuestra misión \"Un Banquete Demasiado Rápido\":\n\n\"Las galaxias que se muestran aquí tienen tanto polvo a su alrededor que la luz brillante de sus quásares no se puede ver en estas imágenes del Telescopio Espacial Hubble de la NASA.\"\n\nLa ciencia nos permite viajar a millones de kilómetros sin salir de casa. ¡Nunca dejes de mirar hacia las estrellas!",
