          "text": "¡Misión iniciada! Abre bien los ojos, porque la NASA nos ha enviado información espectacular directamente desde el espacio.\n\nEl reporte oficial de la NASA nos explica lo siguiente sobre esta imagen de nuestra misión \"El Fósil Luminoso\":\n\n\"Este fotograma de una animación muestra la fusión de dos enanas blancas. Una enana blanca es un remanente extremadamente denso de una estrella que ya no puede quemar combustible nuclear en su núcleo. Ésta es otra forma en que se produce una supernova de \"tipo Ia\".  Las explosiones estelares forjan y distribuyen materiales que componen el mundo en el que vivimos y también contienen pistas sobre la rapidez con la que se expande el universo. Al comprender las supernovas, los científicos pueden descubrir misterios que son clave para saber de qué estamos hechos y el destino de nuestro universo. Pero para tener una visión completa, los científicos deben observar las supernovas desde una variedad de perspectivas,...\"\n\n¡El espacio es asombroso! Recuerda que cada estrella y planeta tiene una historia esperando ser descubierta por científicos como tú.",
