          "text": "¡Iniciando escáneres! Vamos a viajar a la velocidad de la luz para analizar muy de cerca qué ocurre en este rincón de la galaxia.\n\nEl reporte oficial de la NASA nos explica lo siguiente sobre esta imagen de nuestra misión \"Laika: La Perrita de las Calles a las Estrellas\":\n\n\"El Telescopio Espacial Hubble de NASA/ESA observa algunas de las galaxias más hermosas de nuestros cielos: espirales resplandecientes con brillantes viveros estelares, dúos violentos que separan gas y estrellas entre sí mientras se enredan, y galaxias etéreas e irregulares que cuelgan como bandadas de pájaros suspendidas en la negrura del espacio.  Sin embargo, no todas las galaxias, como los humanos, son supermodelos. Esta pequeña espiral, conocida como NGC 4102, tiene un atractivo diferente, con sus brazos espirales bien enrollados y su apariencia discreta pero encantadora.  NGC 4102 se encuentra en la constelación norteña de la Osa Mayor (La Gran...\"\n\n¡El espacio es asombroso! Recuerda que cada estrella y planeta tiene una historia esperando ser descubierta por científicos como tú.",
