          "title": "Apophis, el Imponente Dios Oscuro",
          "text": "¡Atención, equipo de exploración espacial! Prepárense para descubrir uno de los mayores secretos de nuestro universo.\n\nEl reporte oficial de la NASA nos explica lo siguiente sobre esta imagen de nuestra misión \"Apophis, el Imponente Dios Oscuro\":\n\n\"Esta animación muestra la distancia entre el asteroide Apophis y la Tierra en el momento de mayor aproximación del asteroide. Los puntos azules son los numerosos satélites artificiales que orbitan nuestro planeta y el rosa representa la Estación Espacial Internacional.  Película disponible en https://photojournal.jpl.nasa.gov/catalog/PIA23195\"\n\n¡El espacio es asombroso! Recuerda que cada estrella y planeta tiene una historia esperando ser descubierta por científicos como tú.",
